    }


@bp.route("/auth/register", methods=["POST"])
@validate(RegisterSchema)
def register(data):
    if User.query.filter(
        db.or_(User.email == data["email"], User.username == data["username"])
    ).first():
        return {"error": "Username or email already exists"}, 409

    user = User(username=data["username"], email=data["email"])
    user.set_password(data["password"])
    db.session.add(user)
    db.session.commit()

    log_audit("register", "user", resource_id=user.id)
    flush_audit_logs()

    access_token = generate_access_token(user.id)
    refresh_jwt, refresh_token_raw = generate_refresh_token(user.id)

    rt = RefreshTokenModel(
        user_id=user.id,
        token=refresh_token_raw,
        expires_at=RefreshTokenModel.query.session.bind.execute(
            __import__("sqlalchemy").text("SELECT datetime('now', '+7 days')")
        ).scalar() if "sqlite" in current_app.config.get("SQLALCHEMY_DATABASE_URI", "")
        else None,
    )

    from datetime import datetime, timedelta
    rt.expires_at = datetime.utcnow() + timedelta(
        days=current_app.config["JWT_REFRESH_TOKEN_EXPIRE_DAYS"]
    )
    db.session.add(rt)
    db.session.commit()

    return {
        "access_token": access_token,
        "refresh_token": refresh_jwt,
        "user": user.to_dict(),
    }, 201


@bp.route("/auth/login", methods=["POST"])
@rate_limit(5, 60)
@validate(LoginSchema)
def login(data):
    user = User.query.filter_by(email=data["email"]).first()
    if user is None or not user.check_password(data["password"]):
        return {"error": "Invalid email or password"}, 401

    access_token = generate_access_token(user.id)
    refresh_jwt, refresh_token_raw = generate_refresh_token(user.id)

    rt = RefreshTokenModel(
        user_id=user.id,
        token=refresh_token_raw,
